// --- settings file ------------------------------------------------------------
void save() {
    std::string t = g_cfg.serialize();
    if (FILE* f = _wfopen(g_cfgPath.c_str(), L"wb")) {
        fwrite(t.data(), 1, t.size(), f);
        fclose(f);
    }
}

void load() {
    g_cfgPath = dataDir() + L"\\settings.ini";
    FILE* f = _wfopen(g_cfgPath.c_str(), L"rb");
    if (!f) return;
    std::string t;
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) t.append(buf, n);
    fclose(f);
    g_cfg.parse(t);
}

// The saved choice, or the Windows language until there is one.
void applyLanguage() { setEnglish(g_cfg.language.empty() ? !windowsIsSpanish() : g_cfg.language == "en"); }

void setRunAtLogin(bool on) {
    HKEY k;
    if (RegOpenKeyExW(HKEY_CURRENT_USER, L"Software\\Microsoft\\Windows\\CurrentVersion\\Run", 0, KEY_SET_VALUE, &k))
        return;
    if (on) {
        std::wstring v = L"\"" + exePath() + L"\" --hidden";
        RegSetValueExW(k, L"OrbitaXR", 0, REG_SZ, (const BYTE*)v.c_str(), (DWORD)((v.size() + 1) * sizeof(wchar_t)));
    } else {
        RegDeleteValueW(k, L"OrbitaXR");
    }
    RegCloseKey(k);
}

// --- building the window -------------------------------------------------------
HWND add(int page, const wchar_t* cls, const wchar_t* text, DWORD style, int x, int y, int w, int h, int id = 0,
         HFONT font = nullptr) {
    HWND c = CreateWindowExW(0, cls, text, WS_CHILD | style, 0, 0, 0, 0, g_wnd, (HMENU)(INT_PTR)id, g_inst, nullptr);
    SendMessageW(c, WM_SETFONT, (WPARAM)(font ? font : g_font), TRUE);
    g_controls.push_back({c, page, x, y, w, h});
    return c;
}
HWND label(int page, const wchar_t* t, int x, int y, int w, int h = 22, int id = 0, bool grey = false) {
    HWND c = add(page, WC_STATICW, t, SS_LEFT | SS_NOPREFIX, x, y, w, h, id);
    if (grey) g_grey.push_back(c);
    return c;
}
void check(int page, int id, const wchar_t* t, int x, int y, int w = 600) {
    add(page, WC_BUTTONW, t, BS_AUTOCHECKBOX | WS_TABSTOP, x, y, w, 24, id);
}
void combo(int page, int id, int x, int y, int w, std::initializer_list<std::wstring> items) {
    HWND c = add(page, WC_COMBOBOXW, L"", CBS_DROPDOWNLIST | WS_VSCROLL | WS_TABSTOP, x, y, w, 300, id);
    for (auto& s : items) ComboBox_AddString(c, s.c_str());
}
void button(int page, int id, const wchar_t* t, int x, int y, int w, int h = 34) {
    add(page, WC_BUTTONW, t, BS_OWNERDRAW | WS_TABSTOP, x, y, w, h, id);
}
void slider(int page, int id, const wchar_t* t, int y, int lo, int hi) {
    label(page, t, 0, y + 2, 175);
    HWND c = add(page, TRACKBAR_CLASSW, L"", TBS_HORZ | TBS_NOTICKS | WS_TABSTOP, 180, y - 4, 330, 30, id);
    SendMessageW(c, TBM_SETRANGEMIN, FALSE, lo);
    SendMessageW(c, TBM_SETRANGEMAX, TRUE, hi);
    g_values[id] = label(page, L"", 520, y + 2, 94, 22, 0, true);
}

int pos(int id) { return (int)SendMessageW(item(id), TBM_GETPOS, 0, 0); }
void setPos(int id, int v) { SendMessageW(item(id), TBM_SETPOS, TRUE, v); }
bool checked(int id) { return Button_GetCheck(item(id)) == BST_CHECKED; }
void setChecked(int id, bool v) { Button_SetCheck(item(id), v ? BST_CHECKED : BST_UNCHECKED); }
int selection(int id) { return std::max(0, ComboBox_GetCurSel(item(id))); }
void setText(int id, const std::wstring& t) {
    wchar_t cur[4096];
    GetWindowTextW(item(id), cur, 4096);
    if (t != cur) SetWindowTextW(item(id), t.c_str());
}

void makeFonts() {
    for (HFONT f : {g_font, g_bold, g_title, g_big, g_small})
        if (f) DeleteObject(f);
    auto font = [](int pt, int weight) {
        return CreateFontW(-MulDiv(pt, g_dpi, 72), 0, 0, 0, weight, 0, 0, 0, DEFAULT_CHARSET, 0, 0, CLEARTYPE_QUALITY,
                           0, L"Segoe UI");
    };
    g_font = font(10, FW_NORMAL);
    g_bold = font(10, FW_SEMIBOLD);
    g_title = font(17, FW_SEMIBOLD);
    g_big = font(13, FW_SEMIBOLD);
    g_small = font(9, FW_NORMAL);
    if (g_logo) DestroyIcon(g_logo);
    g_logo = (HICON)LoadImageW(g_inst, MAKEINTRESOURCEW(IDI_APP), IMAGE_ICON, S(32), S(32), 0);
}

void layout() {
    for (auto& c : g_controls) {
        SetWindowPos(c.h, nullptr, S(kSidebar + kPad + c.x), S(kHeader + c.y), S(c.w), S(c.ht), SWP_NOZORDER | SWP_NOACTIVATE);
        ShowWindow(c.h, c.page == g_page ? SW_SHOWNA : SW_HIDE);
        int id = GetDlgCtrlID(c.h);
        SendMessageW(c.h, WM_SETFONT, (WPARAM)(id == STATE ? g_big : id == LICENSES ? g_small : g_font), FALSE);
    }
    InvalidateRect(g_wnd, nullptr, TRUE);
}

